body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Oxygen",
    "Ubuntu", "Cantarell", "Fira Sans", "Droid Sans", "Helvetica Neue",
    sans-serif;
  background-color: #f7fafc;
  color: #2d3748;
}

.taskboard-container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 2rem;
}

.taskboard-header {
  text-align: center;
  margin-bottom: 2rem;
}

.taskboard-header h1 {
  font-size: 2.5rem;
  color: #4a5568;
}

.taskboard-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .taskboard-content {
    grid-template-columns: 1fr 1fr;
  }
}

.projects-section, .tasks-section {
  background: white;
  border-radius: 8px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 1.5rem;
}

.projects-section h2, .tasks-section h2 {
  margin-top: 0;
  margin-bottom: 1.5rem;
  border-bottom: 2px solid #e2e8f0;
  padding-bottom: 0.5rem;
  color: #4a5568;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

.project-card {
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 1rem;
  background-color: #f8fafc;
}

.project-card h3 {
  margin-top: 0;
  margin-bottom: 0.75rem;
  color: #2b6cb0;
}

.project-stats {
  margin-bottom: 1rem;
  font-size: 0.95rem;
}

.project-stats p {
  margin: 0.25rem 0;
}

.stat-number {
  font-weight: bold;
  color: #1a202c;
}

.add-task-form {
  display: flex;
  gap: 0.5rem;
}

.add-task-form input {
  flex: 1;
  padding: 0.5rem;
  border: 1px solid #cbd5e0;
  border-radius: 4px;
}

.add-task-form button {
  background-color: #3182ce;
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-weight: 500;
}

.add-task-form button:hover {
  background-color: #2b6cb0;
}

.tasks-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.task-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  border-bottom: 1px solid #e2e8f0;
}

.task-item:last-child {
  border-bottom: none;
}

.task-item.done .task-title {
  text-decoration: line-through;
  color: #a0aec0;
}

.task-info {
  display: flex;
  flex-direction: column;
}

.task-title {
  font-weight: 500;
}

.task-project {
  font-size: 0.8rem;
  color: #718096;
}

.toggle-button {
  background-color: #edf2f7;
  color: #4a5568;
  border: 1px solid #cbd5e0;
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  cursor: pointer;
}

.toggle-button:hover {
  background-color: #e2e8f0;
}

.task-item.done .toggle-button {
  background-color: #e2e8f0;
  color: #718096;
}

.loading, .error {
  text-align: center;
  padding: 3rem;
  font-size: 1.2rem;
}
